using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
namespace Ara {
 public static class BufferPriorityTests {
  static void Assert(bool yes,string why){if(!yes)throw new Exception(why);}
  static State New(int delay,int eating=3){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(8);GridEngine.Ensure(s,d);d.Records.Add(new CellBlock{Id="first-fact",Start=d.Wake.AddMinutes(30+delay),Count=eating,Category="식사",MealId="b1",Score=3,Satisfaction=4});return s;}
  static CellBlock Meal(GridPlan p,string id){return p.Blocks.SingleOrDefault(x=>x.MealId==id);}
  public static void Run(Action<string,Action> check,string dir){
   check("priority: front waiting is spent before shower-tail waiting",()=>{foreach(int delay in new[]{10,20,30}){var s=New(delay);var d=s.Days[0];var p=GridEngine.Build(s,d);var zone=p.Blocks.Single(x=>x.Category=="존2");Assert(zone.Start==d.Records[0].Start.AddMinutes(120-delay)&&zone.Count==4,"front first");Assert(p.FrontWaitSpent==delay&&!p.Changes.Any(x=>x.Contains("존2·샤워→2끼니")),"later buffers unused");Assert(Meal(p,"b10")!=null&&!d.ShowerAfterSecond&&p.Overflow==0,"activities/order retained");}});
   check("priority: sixty minutes uses front thirty then shower-tail thirty without swapping meals",()=>{var s=New(60);var d=s.Days[0];var p=GridEngine.Build(s,d);var meal=Meal(p,"b6");var zone=p.Blocks.Single(x=>x.Category=="존2");var shower=p.Blocks.Single(x=>x.TemplateId=="b5");Assert(meal.Start==d.Records[0].Start.AddHours(3)&&shower.End<=meal.Start.AddMinutes(-10),"meal gap and prep");Assert(zone.Start==d.Records[0].Start.AddMinutes(90)&&p.FrontWaitSpent==30,"front capacity");Assert(!d.ShowerAfterSecond&&Meal(p,"b10")!=null,"no needless swap");int front=p.Changes.FindIndex(x=>x.Contains("1끼니→존2 대기"));int tail=p.Changes.FindIndex(x=>x.Contains("존2·샤워→2끼니"));Assert(front>=0&&tail>front&&p.Overflow==0,"phase order");});
   check("priority: long eating can use meal-before-shower after shower-tail waiting",()=>{var s=New(90,9);var d=s.Days[0];var p=GridEngine.Build(s,d);var meal=Meal(p,"b6");var shower=p.Blocks.Single(x=>x.TemplateId=="b5");Assert(d.ShowerAfterSecond&&shower.Start==meal.End,"meal then shower");int wait=p.Changes.FindIndex(x=>x.Contains("존2·샤워→2끼니"));int swap=p.Changes.FindIndex(x=>x.Contains("존2 → 2끼니 → 샤워"));int third=p.Changes.FindIndex(x=>x.Contains("3끼니 제외"));Assert(wait>=0&&swap>wait&&third>swap,"wait, swap, then third");});
   check("priority: third meal and weight advance occur after front, shower and yogurt-gap buffers",()=>{var s=New(90);var d=s.Days[0];var p=GridEngine.Build(s,d);Assert(Meal(p,"b10")==null&&Meal(p,"b16")!=null,"third before yogurt omission");Assert(p.Blocks.Single(x=>x.Category=="웨이트").Start==Meal(p,"b6").Start.AddMinutes(150),"second start plus150");Assert(p.Changes.FindIndex(x=>x.Contains("존2·샤워→2끼니"))<p.Changes.FindIndex(x=>x.Contains("3끼니 제외")),"wait before third");Assert(p.FrontWaitSpent==30,"retry never adds another thirty");});
   check("priority: fifth meal is omitted before zone2 and zero-benefit cuts are skipped",()=>{var s=New(270);var p=GridEngine.Build(s,s.Days[0]);Assert(Meal(p,"b16")==null&&p.Blocks.Single(x=>x.Category=="존2").Count==4&&p.Blocks.Single(x=>x.Category=="웨이트").Count==12,"yogurt buffer preserves both exercises");Assert(!p.Changes.Any(x=>x.Contains("존2 −")||x.Contains("존2 제외")),"no unhelpful exercise loss");});
   check("priority: when zone omission has real benefit, yogurt was already used",()=>{bool seen=false;foreach(int delay in new[]{200,300,400,500}){var s=New(delay,18);var p=GridEngine.Build(s,s.Days[0]);int omitted=p.Changes.FindIndex(x=>x.Contains("존2 제외"));if(omitted<0)continue;seen=true;int yogurt=p.Changes.FindIndex(x=>x.Contains("요거트")&&x.Contains("제외"));Assert(yogurt>=0&&yogurt<omitted,"yogurt before omission");Assert(!p.Blocks.Any(x=>x.Category=="존2"),"removed only with benefit");}Assert(seen,"omission scenario covered");});
   check("priority: duration and delay sweep preserves meal, recovery, ratings and non-overlap constraints",()=>{foreach(int duration in new[]{3,6,9,18})foreach(int delay in new[]{0,50,70,200,400}){var s=New(delay,duration);var d=s.Days[0];var p=GridEngine.Build(s,d);var meals=p.Blocks.Where(x=>!string.IsNullOrEmpty(x.MealId)).OrderBy(x=>x.Start).ToList();for(int i=1;i<meals.Count;i++)Assert(meals[i].Start>=meals[i-1].Start.AddHours(3),"meal starts >=180");var zone=p.Blocks.SingleOrDefault(x=>x.Category=="존2");if(zone!=null)Assert(zone.Start>=d.Records[0].End.AddHours(1)&&zone.Count>=2,"actual eating recovery and min20");var weights=p.Blocks.Single(x=>x.Category=="웨이트");Assert(weights.Start>=Meal(p,"b6").Start.AddMinutes(150)&&weights.Count>=3,"weight recovery and min30");for(int i=1;i<p.Blocks.Count;i++)Assert(p.Blocks[i].Start>=p.Blocks[i-1].End,"no overlap");Assert(d.Records.Single().Count==duration&&d.Records.Single().Score==3&&d.Records.Single().Satisfaction==4,"facts and both ratings");Assert(Adaptive.EstimatedSleep(s,d,p)==Adaptive.Target(s,d)&&Adaptive.RequiredFinish(s,d,p)>=Adaptive.FourthMealEnd(d,p).Value.AddHours(2),"post fourth meal rest");}});
   check("priority: deleting delayed facts restores original shower order and full routine",()=>{var s=New(60);var d=s.Days[0];GridEngine.Build(s,d);d.Records.Clear();var p=GridEngine.Build(s,d);Assert(!d.ShowerAfterSecond&&p.Blocks.Single(x=>x.TemplateId=="b5").End<Meal(p,"b6").Start,"original shower order");Assert(Meal(p,"b10")!=null&&Meal(p,"b16")!=null,"all routine restored");});
  }
 }
}
